import ScanbotSDK from '../scanbot-sdk';
/**
 * Paper size calculation:
 * - if a standard paper size is given, that paper size is used
 * - otherwise if both paperWidthInches and paperHeightInches is set, those values are used
 * - otherwise the paper size is calculated to fit the input image exactly at the given DPI. If no
 *      DPI value is given, a default DPI of 72 is used.
 *
 * DPI calculation:
 * - if a DPI is given, then that value is used. If the value is not given or
 *      that value is too small for the entire image to fit on the page, then
 *      the smallest possible DPI value is chosen so that the entire image fits on the page.
 */
export interface PdfGenerationOptions {
    dpi?: number;
    standardPaperSize?: 'A4' | 'Letter' | 'Legal';
    paperWidthInches?: number;
    paperHeightInches?: number;
    landscape?: boolean;
}
export default class PdfGenerator {
    _pdfOperation: string;
    _sdk: ScanbotSDK;
    constructor(sdk: ScanbotSDK, pdfOperation: string);
    addPage(imageBuffer: ArrayBuffer): Promise<void>;
    complete(): Promise<ArrayBuffer>;
}
